import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function o(r,e,l,p,c,d){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>The development build uses a user-local bundle loaded by kitty. No root privileges, shell framework, system Python package, Node.js runtime, or network image service belongs in the extension’s normal runtime path.</p><div class="warning custom-block"><p class="custom-block-title">Experimental local artifact</p><p>There is no public download or published package yet. The local release candidate is <code>kittyscape-0.1.0.dev1.tar.gz</code>. Full platform qualification remains in progress; use the <a href="./../reference/compatibility.html">compatibility matrix</a> to see the remaining gates.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Read the exact <a href="./../reference/compatibility.html">compatibility matrix</a>. Test an isolated kitty instance before enabling a daily-use configuration. See <a href="./uninstall.html">uninstall and rollback</a> before applying any setup change.</p><p>The helper checks kitty 0.38.1 or newer and the watcher, timer, image, and directory APIs before changing files. This is a capability check, not a platform support claim.</p><h2 id="choose-the-active-configuration" tabindex="-1">Choose the active configuration <a class="header-anchor" href="#choose-the-active-configuration" aria-label="Permalink to &quot;Choose the active configuration&quot;">​</a></h2><p>Kittyscape’s JSON file belongs in kitty’s active configuration directory, alongside the configuration used for that instance. A custom directory must be passed explicitly to the setup helper. Do not assume every instance uses <code>~/.config/kitty</code>.</p><p>The helper preserves supported symlinked configurations, included files, and existing content. See the <a href="./../development/compatibility-findings.html">runtime findings</a> for the qualified cases.</p><p>The helper rejects configuration paths containing a newline, NUL, or dollar sign, because those paths cannot be represented safely in its kitty include. It also rejects a dangling <code>kitty.conf</code> symlink or a hard-linked <code>kitty.conf</code>. Resolve the reported condition without replacing unrelated user data.</p><h2 id="extract-and-preview" tabindex="-1">Extract and preview <a class="header-anchor" href="#extract-and-preview" aria-label="Permalink to &quot;Extract and preview&quot;">​</a></h2><p>The local build produces the archive, a manifest, and <code>SHA256SUMS</code> in the repository’s <code>dist/</code> directory. Compare the archive’s SHA-256 digest with <code>SHA256SUMS</code> before extracting it. On Linux, use <code>sha256sum</code>; on macOS, use <code>shasum -a 256</code>. The <a href="/evidence/release.json">release record</a> identifies the artifact, executed checks, and open gates.</p><p>From the directory containing the archive:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kittyscape-0.1.0.dev1.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kittyscape-0.1.0.dev1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/tmp/kittyscape trial&#39;</span></span></code></pre></div><p>These commands work in Bash, Zsh, and Fish. Choose your own unused test directory in place of <code>/tmp/kittyscape trial</code>. The final command is a <strong>preview</strong>: it reports the exact files, appended include, and generated keyboard mappings without changing the selected configuration.</p><p>The helper runs in kitty’s embedded Python through <code>+launch</code>. It does not require a system Python installation.</p><h2 id="apply-and-verify" tabindex="-1">Apply and verify <a class="header-anchor" href="#apply-and-verify" aria-label="Permalink to &quot;Apply and verify&quot;">​</a></h2><p>After reviewing the preview:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/tmp/kittyscape trial&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/tmp/kittyscape trial&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>Repeating a valid installation is idempotent: it does not append another include block or silently replace modified installed files. Conflicts are reported so existing content can be preserved.</p><p>Create <code>kittyscape.json</code> in the test directory using the <a href="./getting-started.html">getting-started example</a>. The helper never creates, rewrites, or removes this user-owned rules file. Provide the referenced local images and use directory roots that already exist.</p><p>Open a separate kitty instance using that configuration:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KITTY_CONFIG_DIRECTORY=&#39;/tmp/kittyscape trial&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kitty</span></span></code></pre></div><p>This selects the complete configuration directory, including any automatic theme files, for the new process.</p><p>Check <strong>Ctrl+Shift+F6</strong> for status, then follow the image-switching and restoration checks in <a href="./getting-started.html#check-the-result">getting started</a>. The generated <a href="./../reference/actions.html">lifecycle bindings</a> use Ctrl+Shift+F6 through Ctrl+Shift+F10. Review any existing bindings on those keys before using a personal configuration.</p><p>Finish the evaluation with <a href="./uninstall.html">restore, removal, and rollback</a>. A file-level installation check does not prove graphical restoration or qualify another platform.</p><h2 id="startup-and-existing-windows" tabindex="-1">Startup and existing windows <a class="header-anchor" href="#startup-and-existing-windows" aria-label="Permalink to &quot;Startup and existing windows&quot;">​</a></h2><p>Load the watcher before creating the OS windows it will manage. A fresh kitty process started with the selected configuration, as above, provides a known startup baseline.</p><p>Adding the watcher to an already-running process cannot recover the original image of its existing OS windows. Those windows report <code>baseline-unknown</code> and stay paused. Open a new OS window after the watcher is loaded, or start a fresh kitty process. A new tab or split inside an unknown OS window does not establish a new baseline.</p><h2 id="what-the-helper-owns" tabindex="-1">What the helper owns <a class="header-anchor" href="#what-the-helper-owns" aria-label="Permalink to &quot;What the helper owns&quot;">​</a></h2><p>All paths below are relative to the selected configuration directory.</p><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>kittyscape/0.1.0.dev1/</code></td><td>Versioned runtime and setup bundle.</td></tr><tr><td><code>kittyscape/0.1.0.dev1/kittyscape/location.json</code></td><td>Absolute path to the selected <code>kittyscape.json</code>.</td></tr><tr><td><code>kittyscape.conf</code></td><td>Watcher entry and lifecycle key mappings.</td></tr><tr><td>Marked block in <code>kitty.conf</code></td><td>One include for <code>kittyscape.conf</code>.</td></tr><tr><td><code>kittyscape/kitty.conf.backup</code></td><td>Original configuration snapshot for verified rollback.</td></tr><tr><td><code>kittyscape/install-receipt.json</code></td><td>Ownership and integrity information.</td></tr></tbody></table><p>Existing symlinked <code>kitty.conf</code> files and included files retain their relationships. The helper checks owned-file hashes before replacement or removal. It preserves later unrelated configuration edits during uninstall.</p><h2 id="manual-installation" tabindex="-1">Manual installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual installation&quot;">​</a></h2><p>The helper is optional. For manual setup, use an empty destination, keep a backup and a written inventory of your changes, and copy the extracted bundle into <code>kittyscape/0.1.0.dev1/</code> beneath the selected configuration root. Do not overwrite an existing directory.</p><p>Create <code>kittyscape/location.json</code> <strong>inside the copied bundle</strong>, with the selected absolute JSON path. Its full location is <code>kittyscape/0.1.0.dev1/kittyscape/location.json</code> beneath the configuration root:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tmp/kittyscape trial/kittyscape.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Create a separate include file containing the watcher entry and whichever lifecycle mappings you want. For the example directory above:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watcher /tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/watcher.py</span></span>
<span class="line"><span>map ctrl+shift+f6 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; status</span></span>
<span class="line"><span>map ctrl+shift+f7 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; pause</span></span>
<span class="line"><span>map ctrl+shift+f8 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; resume</span></span>
<span class="line"><span>map ctrl+shift+f9 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; reload</span></span>
<span class="line"><span>map ctrl+shift+f10 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; restore</span></span></code></pre></div><p>Add one <code>include /absolute/path/to/your/include.conf</code> line to the intended kitty configuration. Keep your <code>kittyscape.json</code> and images separate from runtime files. Follow the <a href="#startup-and-existing-windows">startup requirement</a>, then run the same isolated checks.</p><p>A manual installation has no helper ownership receipt. Follow the <a href="./uninstall.html#manual-removal">manual removal instructions</a> using your recorded inventory.</p><h2 id="updates-and-recovery" tabindex="-1">Updates and recovery <a class="header-anchor" href="#updates-and-recovery" aria-label="Permalink to &quot;Updates and recovery&quot;">​</a></h2><p>Keep the previous local bundle and valid configuration until the new artifact passes its checks. Use the shipped rollback path if installation cannot be verified. The <a href="./../releases.html">release notes</a> record compatibility changes; an unqualified upgrade must not inherit the previous version’s support label.</p>`,43)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
